pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title TicTacToe
 * @notice A gas-optimized, secure PvP Tic Tac Toe game with wagering.
 * @dev Implements Pull-over-Push payments, strictly packed storage, and bitwise board logic.
 */
contract TicTacToe is ReentrancyGuard {
    // ═══════════════════════════════════════════════════════════════
    // ERRORS
    // ═══════════════════════════════════════════════════════════════
    error IncorrectStake(uint256 sent, uint256 required);
    error GameNotJoinable();
    error GameNotActive();
    error NotYourTurn();
    error CellOccupied();
    error InvalidCell();
    error TimeoutNotReached(uint256 currentTime, uint256 deadline);
    error NoWinningsToWithdraw();
    error TransferFailed();
    error SelfPlayNotAllowed();

    // ═══════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════
    event GameCreated(uint256 indexed gameId, address indexed player1, uint256 stake);
    event GameJoined(uint256 indexed gameId, address indexed player2);
    event MoveMade(uint256 indexed gameId, address indexed player, uint8 cell);
    event GameWon(uint256 indexed gameId, address indexed winner, uint256 amount);
    event GameDraw(uint256 indexed gameId);
    event TimeoutClaimed(uint256 indexed gameId, address indexed winner);
    event Withdrawn(address indexed player, uint256 amount);

    // ═══════════════════════════════════════════════════════════════
    // TYPES & CONSTANTS
    // ═══════════════════════════════════════════════════════════════

    // Status enum fits in uint8
    enum GameStatus { WAITING, ACTIVE }

    struct Game {
        // SLOT 0 (Packed: 20+4+2+1+1 = 28 bytes)
        address player1;      // 160 bits
        uint32 lastAction;    // 32 bits
        uint16 board;         // 16 bits (2 bits per cell, 9 cells)
        uint8 turnCount;      // 8 bits
        GameStatus status;    // 8 bits

        // SLOT 1 (Packed: 20+12 = 32 bytes)
        address player2;      // 160 bits
        uint96 stake;         // 96 bits (Max ~7.9e28 wei)
    }

    uint256 public constant TIMEOUT = 1 hours;

    // ═══════════════════════════════════════════════════════════════
    // STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════

    /// @notice Tracks all game sessions
    mapping(uint256 => Game) public games;

    /// @notice Tracks user winnings for withdrawal (Pull pattern)
    mapping(address => uint256) public pendingWithdrawals;

    /// @notice Counter for generating game IDs
    uint256 public gameIdCounter;

    // ═══════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    constructor() {
        // Empty constructor as required
    }

    // ═══════════════════════════════════════════════════════════════
    // EXTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Create a new game, optionally staking ETH.
     * @return gameId The unique ID of the created game.
     */
    function createGame() external payable returns (uint256 gameId) {
        unchecked {
            gameId = ++gameIdCounter;
        }

        Game storage game = games[gameId];
        game.player1 = msg.sender;
        game.stake = uint96(msg.value);
        game.lastAction = uint32(block.timestamp);
        game.status = GameStatus.WAITING;

        emit GameCreated(gameId, msg.sender, msg.value);
    }

    /**
     * @notice Join an existing game by matching the stake.
     * @param gameId The ID of the game to join.
     */
    function joinGame(uint256 gameId) external payable {
        Game storage game = games[gameId];

        if (game.status != GameStatus.WAITING) revert GameNotJoinable();
        if (msg.value != uint256(game.stake)) revert IncorrectStake(msg.value, game.stake);
        if (msg.sender == game.player1) revert SelfPlayNotAllowed();

        game.player2 = msg.sender;
        game.status = GameStatus.ACTIVE;
        game.lastAction = uint32(block.timestamp);

        emit GameJoined(gameId, msg.sender);
    }

    /**
     * @notice Place a mark on the board.
     * @param gameId The game ID.
     * @param cell Index of the cell (0-8).
     */
    function makeMove(uint256 gameId, uint8 cell) external {
        if (cell > 8) revert InvalidCell();

        // Cache storage to stack to save gas
        Game storage game = games[gameId];

        // Load Slot 0
        address p1 = game.player1;
        uint16 brd = game.board;
        uint8 turns = game.turnCount;
        GameStatus stat = game.status;

        // Check game active
        if (stat != GameStatus.ACTIVE) revert GameNotActive();

        // Determine turn (Player 1 on even turns, Player 2 on odd)
        bool isP1Turn = (turns & 1) == 0;
        address expectedPlayer = isP1Turn ? p1 : game.player2; // Read p2 from Slot 1 if needed

        if (msg.sender != expectedPlayer) revert NotYourTurn();

        // Check cell availability (bits at pos cell*2 must be 0)
        // 2 bits per cell mask = 3 (binary 11)
        if (((brd >> (cell * 2)) & 3) != 0) revert CellOccupied();

        // Update state
        unchecked {
            // Determine player value: 1 for P1, 2 for P2
            uint16 playerVal = isP1Turn ? 1 : 2;

            // Set bits
            brd |= (playerVal << (cell * 2));
            turns++;
        }

        // Write back to storage (Slot 0 update)
        game.board = brd;
        game.turnCount = turns;
        game.lastAction = uint32(block.timestamp);

        emit MoveMade(gameId, msg.sender, cell);

        // Win check
        uint8 playerNum = isP1Turn ? 1 : 2;
        if (_checkWin(brd, playerNum)) {
            _endGame(gameId, game, msg.sender);
            return;
        }

        // Draw check
        if (turns == 9) {
            _drawGame(gameId, game);
        }
    }

    /**
     * @notice Claim the pot if the opponent has timed out.
     * @param gameId The game ID.
     */
    function claimTimeout(uint256 gameId) external {
        Game storage game = games[gameId];

        if (game.status != GameStatus.ACTIVE) revert GameNotActive();

        uint256 deadline;
        unchecked {
            deadline = uint256(game.lastAction) + TIMEOUT;
        }

        if (block.timestamp <= deadline) {
            revert TimeoutNotReached(block.timestamp, deadline);
        }

        // Identify who timed out
        // If turnCount is even -> P1's turn -> P1 timed out -> P2 wins
        bool isP1Turn = (game.turnCount & 1) == 0;
        address winner = isP1Turn ? game.player2 : game.player1;

        _endGame(gameId, game, winner);

        emit TimeoutClaimed(gameId, winner);
    }

    /**
     * @notice Withdraw pending funds.
     */
    function withdraw() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        if (amount == 0) revert NoWinningsToWithdraw();

        // Effects
        pendingWithdrawals[msg.sender] = 0;

        // Interactions
        (bool success, ) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit Withdrawn(msg.sender, amount);
    }

    // ═══════════════════════════════════════════════════════════════
    // INTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @dev Handles game completion and fund distribution.
     * Deletes game struct to refund gas.
     */
    function _endGame(uint256 gameId, Game storage game, address winner) internal {
        uint256 stake = game.stake;

        // Effects: Credit winner
        if (stake > 0) {
            unchecked {
                pendingWithdrawals[winner] += uint256(stake) * 2;
            }
        }

        // Effects: Clear state (Gas Refund)
        delete games[gameId];

        emit GameWon(gameId, winner, uint256(stake) * 2);
    }

    /**
     * @dev Handles game draw and stake refunds.
     */
    function _drawGame(uint256 gameId, Game storage game) internal {
        uint256 stake = game.stake;
        address p1 = game.player1;
        address p2 = game.player2;

        // Effects: Refund both
        if (stake > 0) {
            unchecked {
                pendingWithdrawals[p1] += stake;
                pendingWithdrawals[p2] += stake;
            }
        }

        // Effects: Clear state
        delete games[gameId];

        emit GameDraw(gameId);
    }

    /**
     * @dev Efficient bitwise check for win conditions.
     */
    function _checkWin(uint16 board, uint8 p) internal pure returns (bool) {
        // We look for 3 marks of player 'p' in a row/col/diag.
        // p is 1 (binary 01) or 2 (binary 10).

        // ROWS
        // Row 0: Bits 0-5. Mask 0x3F. Value must equal p | p<<2 | p<<4
        uint16 pRow = uint16(p) | (uint16(p) << 2) | (uint16(p) << 4); // 0x15 or 0x2A

        if ((board & 0x3F) == pRow) return true;            // Row 0
        if (((board >> 6) & 0x3F) == pRow) return true;     // Row 1
        if (((board >> 12) & 0x3F) == pRow) return true;    // Row 2

        // COLS
        // Col 0: Cells 0, 3, 6
        if (_isP(board, 0, p) && _isP(board, 3, p) && _isP(board, 6, p)) return true;
        // Col 1: Cells 1, 4, 7
        if (_isP(board, 1, p) && _isP(board, 4, p) && _isP(board, 7, p)) return true;
        // Col 2: Cells 2, 5, 8
        if (_isP(board, 2, p) && _isP(board, 5, p) && _isP(board, 8, p)) return true;

        // DIAGS
        // Diag 0: Cells 0, 4, 8
        if (_isP(board, 0, p) && _isP(board, 4, p) && _isP(board, 8, p)) return true;
        // Diag 1: Cells 2, 4, 6
        if (_isP(board, 2, p) && _isP(board, 4, p) && _isP(board, 6, p)) return true;

        return false;
    }

    /**
     * @dev Helper to check if a cell contains player p's mark.
     */
    function _isP(uint16 board, uint8 cell, uint8 p) internal pure returns (bool) {
        return ((board >> (cell * 2)) & 3) == p;
    }
}
